    if (wouldExceedLimit(org.plan, "seats", seatsInUse, 0)) {
      const limits = getPlanLimits(org.plan);
      throw new Error(`Plan ${org.plan} includes ${limits.seats} seats and ${seatsInUse} are taken`);
    }
  }

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
